//! 🌐️ Public HTML factory, typed file and external markup controls share the neutral cohort.
use super::*;
use {semio_framework_artifact_reference::ArtifactDialect,semio_framework_os_kernel::io_schema::IoPayload,semio_framework_os_kernel::io_schema::IoFidelity,semio_framework_os_kernel::io_schema::SQLITE_SNAPSHOT,semio_framework_os_kernel::io::io_mechanism::io_route,semio_framework_os_kernel::io::io_mechanism::io_run_with_snapshot_control,semio_framework_os_kernel::io::io_mechanism::io_export_sqlite_snapshot,semio_framework_os_kernel::io::io_mechanism::io_import_sqlite_snapshot,semio_framework_os_kernel::io::io_mechanism::native_snapshot_sqlite_schema};
use semio_framework_async_macros::async_test;
use std::{any::TypeId,io::Write,process::{Command,Stdio}};
fn cohort()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🚦️cohort/🔣️.json")).unwrap()}
fn node(value:&serde_json::Value)->HtmlNode{match value["kind"].as_str().unwrap(){
 "element"=>HtmlNode::Element{name:value["name"].as_str().unwrap().into(),attributes:value["attributes"].as_array().unwrap().iter().map(|a|HtmlAttr{name:a["name"].as_str().unwrap().into(),value:a.get("value").map(|v|v.as_str().unwrap().into())}).collect(),children:value["children"].as_array().unwrap().iter().map(node).collect()},
 "text"=>HtmlNode::Text{text:value["text"].as_str().unwrap().into()},"comment"=>HtmlNode::Comment{text:value["text"].as_str().unwrap().into()},"rawText"=>HtmlNode::RawText{parent_kind:match value["parentKind"].as_str().unwrap(){"script"=>RawTextKind::Script,"style"=>RawTextKind::Style,_=>panic!("neutral raw kind")},text:value["text"].as_str().unwrap().into()},_=>panic!("neutral node kind")}}
fn owned(value:&serde_json::Value)->HtmlSnapshot{HtmlSnapshot{schema:value["schema"].as_str().unwrap().into(),doctype:value.get("doctype").map(|v|v.as_str().unwrap().into()),root:node(&value["root"])}}
fn dialect()->ArtifactDialect{ArtifactDialect{artifact_kind:"s.stdio.html".into(),standard:"5".into(),subset:"*".into()}}
fn publish(){semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("HTML public SQLite cohort").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();}
fn native()->HtmlSnapshot{parse_html_document(cohort()["nativeHtml"].as_str().unwrap()).unwrap()}
fn payload(snapshot:&HtmlSnapshot,encoding:SnapshotEncoding)->IoPayload{match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(store::ArtifactPack::encode_pack(snapshot)),SnapshotEncoding::Text=>IoPayload::Text(store::ArtifactDsl::print_dsl(snapshot))}}
fn edit(bytes:&[u8],sql:&str)->Vec<u8>{let script="import {Database} from 'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));d.exec('PRAGMA foreign_keys=OFF;PRAGMA ignore_check_constraints=ON;');d.exec(process.env.HTML_COHORT_SQL);if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok')throw Error('physical integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut c=Command::new("bun").args(["-e",script]).env("HTML_COHORT_SQL",sql).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();c.stdin.take().unwrap().write_all(bytes).unwrap();let result=c.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));result.stdout}
#[test]
fn sqlite_snapshot_html_public_factory_exact_owner_metadata(){let f=crate::native_codecs();assert_eq!(f.len(),1);assert_eq!(f[0].id,cohort()["factory"].as_str().unwrap());let c=(f[0].codec)();assert_eq!(c.schema,"stdio.html");assert_eq!(c.extension,"html");let p=c.snapshot_sqlite.expect("actual factory must own SQLite capability");assert_eq!(p.snapshot_type,Some(TypeId::of::<HtmlSnapshot>()));assert_eq!(p.schema,HtmlSnapshot::SQLITE_SCHEMA);assert_eq!(c.pack_schema_hash,semio_framework_hash::Sha256::digest(include_bytes!("../../../../💾️binary/📸️snapshot/📡️.protocol.semio")));}
#[async_test]
async fn sqlite_snapshot_html_public_declaration_typed_file_every_literal_field(){publish();assert!(native_snapshot_sqlite_schema(&dialect()).unwrap().contains("html_attribute"));let c=cohort();for source in std::iter::once(&c["owned"]).chain(c["variants"].as_array().unwrap()){let value=owned(source);for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let bytes=io_export_sqlite_snapshot(&dialect(),&value,encoding,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap().value;assert_eq!(io_import_sqlite_snapshot::<HtmlSnapshot>(&dialect(),&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value,value);assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}}}
#[async_test]
async fn sqlite_snapshot_html_public_native_exact_routes_both_encodings(){publish();let d=dialect();let s=ArtifactDialect::from(SQLITE_SNAPSHOT);let value=native();for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let export=io_route(&d,&s,1).await.unwrap().value;let import=io_route(&s,&d,1).await.unwrap().value;assert_eq!(export.hops.len(),1);assert_eq!(import.hops.len(),1);assert_eq!(export.fidelity,IoFidelity::Exact);let input=payload(&value,encoding);let mut phases=Vec::new();let file=io_run_with_snapshot_control(&export,input.clone(),SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap().value;let output=io_run_with_snapshot_control(&import,file,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap().value;assert!(output==input,"literal native payload differs from owning encoder");assert!(phases.contains(&SqliteSnapshotPhase::DecodeNative));assert!(phases.contains(&SqliteSnapshotPhase::EncodeNative));}}
#[async_test]
async fn sqlite_snapshot_html_public_plugin_wrapper_uses_actual_factory(){use semio_framework_plugin::{plugin_runtime::{plugin_snapshot_sqlite_schema,plugin_snapshot_sqlite_export,plugin_snapshot_sqlite_import},sqlite_wire::{SnapshotInput,SnapshotLimits,SnapshotFileResult,SnapshotPayloadResult}};publish();assert!(plugin_snapshot_sqlite_schema("s.stdio.html@5/*").unwrap().contains("html_raw_text"));for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let value=native();let input=payload(&value,encoding);let (kind,bytes)=match &input{IoPayload::Binary(b)=>("binary",b.clone()),IoPayload::Text(t)=>("text",t.as_bytes().to_vec())};let file=match plugin_snapshot_sqlite_export(SnapshotInput{dialect:"s.stdio.html@5/*".into(),encoding:kind.into(),payload:bytes.clone(),limits:SnapshotLimits::from(SqliteDatabaseLimits::default())}).await.unwrap(){SnapshotFileResult::Done(file)=>file,SnapshotFileResult::Rejected(error)=>panic!("public export refused: {}",error.message)};let restored=match plugin_snapshot_sqlite_import(SnapshotInput{dialect:"s.stdio.html@5/*".into(),encoding:kind.into(),payload:file.bytes,limits:SnapshotLimits::from(SqliteDatabaseLimits::default())}).await.unwrap(){SnapshotPayloadResult::Done(value)=>value,SnapshotPayloadResult::Rejected(error)=>panic!("public import refused: {}",error.message)};assert_eq!(restored.encoding,kind);assert_eq!(restored.bytes,bytes);}}
#[async_test]
async fn sqlite_snapshot_html_public_typed_renumber_has_no_traversal_identity(){publish();let c=cohort();let value=owned(&c["owned"]);let bytes=io_export_sqlite_snapshot(&dialect(),&value,SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;let edited=edit(&bytes,c["renumberSql"].as_str().unwrap());assert_eq!(io_import_sqlite_snapshot::<HtmlSnapshot>(&dialect(),&edited,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value,value);}
#[async_test]
async fn sqlite_snapshot_html_public_malformed_graph_and_metadata_rejection(){publish();let c=cohort();let bytes=io_export_sqlite_snapshot(&dialect(),&owned(&c["owned"]),SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;for alteration in c["invalidEdits"].as_array().unwrap(){let changed=edit(&bytes,alteration.as_str().unwrap());assert!(io_import_sqlite_snapshot::<HtmlSnapshot>(&dialect(),&changed,SqliteDatabaseLimits::default(),&mut |_|true).await.is_err(),"{}",alteration);}let changed=edit(&bytes,"UPDATE semio_snapshot SET subset='foreign-owner';");assert!(io_import_sqlite_snapshot::<HtmlSnapshot>(&dialect(),&changed,SqliteDatabaseLimits::default(),&mut |_|true).await.is_err());}
#[async_test]
async fn sqlite_snapshot_html_public_complete_file_exact_ceiling_and_metadata_row(){publish();let value=native();let limits=SqliteDatabaseLimits::default();let bytes=io_export_sqlite_snapshot(&dialect(),&value,SnapshotEncoding::Text,limits,&mut |_|true).await.unwrap().value;let exact=SqliteDatabaseLimits{max_file_bytes:bytes.len(),..limits};assert_eq!(io_import_sqlite_snapshot::<HtmlSnapshot>(&dialect(),&bytes,exact,&mut |_|true).await.unwrap().value,value);assert!(io_import_sqlite_snapshot::<HtmlSnapshot>(&dialect(),&bytes,SqliteDatabaseLimits{max_file_bytes:bytes.len()-1,..limits},&mut |_|true).await.is_err());let rows=project(&value).tables.iter().map(|t|t.rows.len()).sum::<usize>();assert!(io_export_sqlite_snapshot(&dialect(),&value,SnapshotEncoding::Text,SqliteDatabaseLimits{max_rows:rows,..limits},&mut |_|true).await.is_err());assert!(io_export_sqlite_snapshot(&dialect(),&value,SnapshotEncoding::Text,SqliteDatabaseLimits{max_rows:rows+1,..limits},&mut |_|true).await.is_ok());}
#[test]
fn sqlite_snapshot_html_public_owner_controlled_native_long_unicode_and_recovery(){let value=HtmlSnapshot{schema:"stdio.html".into(),doctype:None,root:HtmlNode::Element{name:"html".into(),attributes:Vec::new(),children:vec![HtmlNode::Text{text:"Grüße 🌠 &<>".repeat(10000)}]}};let d=dialect();let codec=(crate::native_codecs()[0].codec)().snapshot_sqlite.unwrap();for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let input=payload(&value,encoding);let mut seen=false;let mut cb=|p:SqliteSnapshotProgress|{let stop=p.phase==SqliteSnapshotPhase::DecodeNative&&p.completed>=65536&&p.completed<p.total;seen|=stop;!stop};assert!((codec.export)("stdio.html",&d,&input,&mut SqliteSnapshotControl::new(&mut cb,SqliteDatabaseLimits::default())).is_err());assert!(seen,"actual input scan must expose an interior byte stage");let db=project(&value);let mut seen=false;let mut cb=|p:SqliteSnapshotProgress|{let stop=p.phase==SqliteSnapshotPhase::EncodeNative&&p.completed>=65536&&p.completed<p.total;seen|=stop;!stop};assert!((codec.import)("stdio.html",&d,db,encoding,&mut SqliteSnapshotControl::new(&mut cb,SqliteDatabaseLimits::default())).is_err());assert!(seen,"actual markup output must expose an interior byte stage");let output=(codec.import)("stdio.html",&d,project(&value),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert!(output==input,"literal native payload differs from owning encoder");}}
#[test]
fn sqlite_snapshot_html_public_semantic_long_fields_cancel_each_direction(){for field in 0..8{let mut value=owned(&cohort()["owned"]);let text="x".repeat(100000);match field{0=>value.schema=text,1=>value.doctype=Some(text),2=>if let HtmlNode::Element{name,..}=&mut value.root{*name=text},3|4=>if let HtmlNode::Element{attributes,..}=&mut value.root{if field==3{attributes[0].name=text}else{attributes[0].value=Some(text)}},_=>if let HtmlNode::Element{children,..}=&mut value.root{children[0]=match field{5=>HtmlNode::Text{text},6=>HtmlNode::Comment{text},_=>HtmlNode::RawText{parent_kind:RawTextKind::Script,text}}}}let db=project(&value);for phase in [SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut seen=false;let mut cb=|p:SqliteSnapshotProgress|{let stop=p.phase==phase&&p.completed>=65536&&p.completed<p.total;seen|=stop;!stop};let mut control=SqliteSnapshotControl::new(&mut cb,SqliteDatabaseLimits::default());let failed=if phase==SqliteSnapshotPhase::ProjectSnapshot{value.to_sqlite_database(&mut control).is_err()}else{HtmlSnapshot::from_sqlite_database(&db,&mut control).is_err()};assert!(failed&&seen,"field {field}, phase {phase:?}");}}}
#[test]
fn sqlite_snapshot_html_public_deep_native_guarded_partial_and_owner_retirement(){let mut value=HtmlSnapshot{schema:"stdio.html".into(),doctype:None,root:HtmlNode::Text{text:"leaf".into()}};for _ in 0..2048{value.root=HtmlNode::Element{name:"div".into(),attributes:Vec::new(),children:vec![value.root]};}let codec=(crate::native_codecs()[0].codec)().snapshot_sqlite.unwrap();for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let input=payload(&value,encoding);let db=(codec.export)("stdio.html",&dialect(),&input,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let output=(codec.import)("stdio.html",&dialect(),db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert!(output==input,"literal native payload differs from owning encoder");}value.retire_sqlite_snapshot();}

#[test]
fn sqlite_snapshot_html_public_native_truncation_grammar_and_envelope_refusal(){let codec=(crate::native_codecs()[0].codec)().snapshot_sqlite.unwrap();for raw in cohort()["invalidNativeHtml"].as_array().unwrap(){for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let envelope=store::semio_format::SemioEnvelope::from_envelope_id("stdio.html",match encoding{SnapshotEncoding::Binary=>store::semio_format::Component::Pack,SnapshotEncoding::Text=>store::semio_format::Component::Dsl},1).unwrap();let raw=raw.as_str().unwrap();let input=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(store::semio_format::wrap_binary(&envelope,raw.as_bytes())),SnapshotEncoding::Text=>IoPayload::Text(store::semio_format::wrap_text(&envelope,raw))};assert!((codec.export)("stdio.html",&dialect(),&input,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}}let envelope=store::semio_format::SemioEnvelope::from_envelope_id("foreign.html",store::semio_format::Component::Pack,1).unwrap();let input=IoPayload::Binary(store::semio_format::wrap_binary(&envelope,cohort()["nativeHtml"].as_str().unwrap().as_bytes()));assert!((codec.export)("stdio.html",&dialect(),&input,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_html_public_native_resource_admission_and_wide_known_progress(){let mut value=native();if let HtmlNode::Element{children,..}=&mut value.root{*children=(0..1024).map(|_|HtmlNode::Element{name:"span".into(),attributes:Vec::new(),children:vec![HtmlNode::Text{text:"literal".into()}]}).collect();}let codec=(crate::native_codecs()[0].codec)().snapshot_sqlite.unwrap();let rows=project(&value).tables.iter().map(|table|table.rows.len()).sum::<usize>();for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let input=payload(&value,encoding);for limits in [SqliteDatabaseLimits{max_rows:rows-1,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_value_bytes:256,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_file_bytes:1,..SqliteDatabaseLimits::default()}]{assert!((codec.export)("stdio.html",&dialect(),&input,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!((codec.import)("stdio.html",&dialect(),project(&value),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}let mut seen=false;let mut callback=|p:SqliteSnapshotProgress|{let stop=p.phase==SqliteSnapshotPhase::DecodeNative&&p.completed>=256&&p.completed<p.total;seen|=stop;!stop};assert!((codec.export)("stdio.html",&dialect(),&input,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(seen);assert!((codec.import)("stdio.html",&dialect(),project(&value),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value==input,"wide canonical native wire differs");}}


fn literal_markup(source:&str,encoding:SnapshotEncoding)->IoPayload{let component=match encoding{SnapshotEncoding::Binary=>store::semio_format::Component::Pack,SnapshotEncoding::Text=>store::semio_format::Component::Dsl};let envelope=store::semio_format::SemioEnvelope::from_envelope_id("stdio.html",component,1).unwrap();match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(store::semio_format::wrap_binary(&envelope,source.as_bytes())),SnapshotEncoding::Text=>IoPayload::Text(store::semio_format::wrap_text(&envelope,source))}}
#[test]
fn sqlite_snapshot_html_public_duplicate_body_normalization_uses_first_literal_owner(){let c=cohort();let a=&c["nativeAudit"]["duplicateBody"];let source=a["source"].as_str().unwrap();let expected=owned(&a["expected"]);assert_eq!(parse_html_document(source).unwrap(),expected);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let restored=HtmlSnapshot::decode_sqlite_snapshot_native(&literal_markup(source,encoding),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(restored,expected);}}
#[test]
fn sqlite_snapshot_html_public_normalized_returned_row_ceiling_excludes_discarded_whitespace(){let c=cohort();let a=&c["nativeAudit"]["normalizedRows"];let source=a["source"].as_str().unwrap();let expected=owned(&a["expected"]);assert_eq!(parse_html_document(source).unwrap(),expected);let count=project(&expected).tables.iter().map(|t|t.rows.len()).sum::<usize>();assert_eq!(count,a["domainRows"].as_u64().unwrap()as usize);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let input=literal_markup(source,encoding);let actual=HtmlSnapshot::decode_sqlite_snapshot_native(&input,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:count,..Default::default()}));assert_eq!(actual.unwrap(),expected);assert!(HtmlSnapshot::decode_sqlite_snapshot_native(&input,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:count-1,..Default::default()})).is_err());}}

#[test]
fn sqlite_snapshot_html_public_native_producers_share_cumulative_construction_admission(){
    let a=cohort()["allocationBridge"].clone();let maximum=usize::try_from(a["maximumBytes"].as_u64().unwrap()).unwrap();let copy=usize::try_from(a["copyBytes"].as_u64().unwrap()).unwrap();let cancel=usize::try_from(a["cancelAt"].as_u64().unwrap()).unwrap();let passes=usize::try_from(a["passes"].as_u64().unwrap()).unwrap();let wire_total=copy+usize::try_from(a["nativeMarkupOverheadBytes"].as_u64().unwrap()).unwrap();let value=native();let long=HtmlSnapshot{schema:"stdio.html".into(),doctype:None,root:HtmlNode::Element{name:"html".into(),attributes:Vec::new(),children:vec![HtmlNode::Text{text:"x".repeat(copy)}]}};
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let input=payload(&value,encoding);
        for phase in [SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::EncodeNative]{
            let mut callback=|_:SqliteSnapshotProgress|true;let limits=SqliteDatabaseLimits{max_allocation_bytes:maximum,..Default::default()};let mut probe=SqliteSnapshotControl::new(&mut callback,limits);
            if phase==SqliteSnapshotPhase::DecodeNative{HtmlSnapshot::decode_sqlite_snapshot_native(&input,&mut probe).unwrap();}else{value.encode_sqlite_snapshot_native(encoding,&mut probe).unwrap();}
            let used=maximum-probe.allocation_remaining_bytes();assert!(used>0,"actual native producer must transfer its owned backing admission");
            let mut callback=|_:SqliteSnapshotProgress|true;let mut exact=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits{max_allocation_bytes:used,..limits});
            for pass in 0..passes{let result=if phase==SqliteSnapshotPhase::DecodeNative{HtmlSnapshot::decode_sqlite_snapshot_native(&input,&mut exact).map(|_|())}else{value.encode_sqlite_snapshot_native(encoding,&mut exact).map(|_|())};assert_eq!(result.is_ok(),pass==0,"same owner must not reset cumulative construction admission");}assert_eq!(exact.allocation_remaining_bytes(),0);
            if encoding==SnapshotEncoding::Binary&&phase==SqliteSnapshotPhase::DecodeNative{let mut reached=false;let mut callback=|p:SqliteSnapshotProgress|{let stop=p.phase==phase&&p.total==wire_total&&p.completed>=cancel&&p.completed<p.total;reached|=stop;!stop};let mut borrowed=SqliteSnapshotControl::new(&mut callback,limits);assert!(HtmlSnapshot::decode_sqlite_snapshot_native(&payload(&long,encoding),&mut borrowed).is_err());let used=maximum-borrowed.allocation_remaining_bytes();assert!(reached);assert_eq!(used,usize::try_from(a["borrowedValidationAllocationBytes"].as_u64().unwrap()).unwrap(),"borrowed UTF-8 validation must not claim owned backing");}
            let mut reached=false;let mut callback=|p:SqliteSnapshotProgress|{let owned_total=if phase==SqliteSnapshotPhase::DecodeNative{copy}else{wire_total};let stop=p.phase==phase&&p.total==owned_total&&p.completed>=cancel&&p.completed<p.total;reached|=stop;!stop};let mut interrupted=SqliteSnapshotControl::new(&mut callback,limits);let input=payload(&long,encoding);let result=if phase==SqliteSnapshotPhase::DecodeNative{HtmlSnapshot::decode_sqlite_snapshot_native(&input,&mut interrupted).map(|_|())}else{long.encode_sqlite_snapshot_native(encoding,&mut interrupted).map(|_|())};let remaining=interrupted.allocation_remaining_bytes();assert!(result.is_err()&&reached);assert!(remaining<maximum,"interior refusal must settle admitted backing without refund");
        }
        let mut callback=|_:SqliteSnapshotProgress|true;let mut tiny=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits{max_allocation_bytes:usize::try_from(a["refusedBytes"].as_u64().unwrap()).unwrap(),..Default::default()});assert!(HtmlSnapshot::decode_sqlite_snapshot_native(&input,&mut tiny).is_err());
    }
}
